/* Utils.js */
const Utils={clamp(v,min,max){return v<min?min:v>max?max:v;},lerp(a,b,t){return a+(b-a)*t;},dist2(x1,y1,x2,y2){const dx=x1-x2,dy=y1-y2;return dx*dx+dy*dy;},dist(x1,y1,x2,y2){return Math.sqrt(Utils.dist2(x1,y1,x2,y2));},circleHit(x1,y1,r1,x2,y2,r2){const rsum=r1+r2;return Utils.dist2(x1,y1,x2,y2)<rsum*rsum;},rad(deg){return deg*Math.PI/180;},deg(rad){return rad*180/Math.PI;},angleDiff(a,b){let d=(b-a)%360;if(d>180)d-=360;if(d<-180)d+=360;return d;},rotateToward(curAngle,targetAngle,maxStep){const diff=Utils.angleDiff(curAngle,targetAngle);if(Math.abs(diff)<=maxStep)return targetAngle;return(curAngle+Math.sign(diff)*maxStep+360)%360;},vecFromAngle(deg){const r=Utils.rad(deg);return{x:Math.cos(r),y:Math.sin(r)};},angleFromVec(x,y){return(Utils.deg(Math.atan2(y,x))+360)%360;},rnd(){return Math.random();},rndInt(min,max){return Math.floor(min+Math.random()*(max-min+1));},rndRange(min,max){return min+Math.random()*(max-min);},chance(p){return Math.random()<p;},pick(arr){return arr[Math.floor(Math.random()*arr.length)];},hexToRgba(hex,alpha=1){const h=hex.replace('#','');const r=parseInt(h.substring(0,2),16);const g=parseInt(h.substring(2,4),16);const b=parseInt(h.substring(4,6),16);return`rgba(${r},${g},${b},${alpha})`;},drawGlowCircle(ctx,x,y,r,color,glow=8){ctx.save();ctx.shadowBlur=glow;ctx.shadowColor=color;ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.restore();},drawGlowLine(ctx,x1,y1,x2,y2,color,width=2,glow=10){ctx.save();ctx.shadowBlur=glow;ctx.shadowColor=color;ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.restore();},clipCorner(ctx,x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w,y);ctx.lineTo(x+w,y+h-r);ctx.lineTo(x+w-r,y+h);ctx.lineTo(x,y+h);ctx.lineTo(x,y+r);ctx.closePath();},noise(t){return(Math.sin(t*12.9898)*43758.5453)%1;},TAU:Math.PI*2,};
