if(Game.addCoins){const cr=Balance.coin?Balance.coin.rewards[enemy.type]:0;const base=cr!==undefined?cr:(Balance.coin?Balance.coin.defaultReward:0);Game.addCoins(Math.round(base*this.coinMult));}
