/* Collision.js */
const Collision={detect(){if(!Game.player)return;const player=Game.player;PlayerBulletPool.forEachActive(b=>{for(let i=0;i<Game.enemies.length;i++){const e=Game.enemies[i];if(!e.alive)continue;if(Utils.circleHit(b.x,b.y,b.radius,e.x,e.y,e.radius)){e.damage(b.damage,player);if(b.pierce===0){b.active=false;b.dead=true;}
else if(b.pierce>0)b.pierce--;break;}}
if(Game.boss&&Game.boss.alive&&Game.boss.state!=='intro'&&Game.boss.state!=='dead'){const boss=Game.boss;for(let i=0;i<boss.turrets.length;i++){const t=boss.turrets[i];if(Utils.circleHit(b.x,b.y,b.radius,t.x,t.y,t.radius)){t.damage(b.damage);if(b.pierce===0){b.active=false;b.dead=true;}
else if(b.pierce>0)b.pierce--;return;}}
if(boss.invulnerable)return;if(Utils.circleHit(b.x,b.y,b.radius,boss.x,boss.y,boss.radius)){boss.damage(b.damage,player);if(b.pierce===0){b.active=false;b.dead=true;}
else if(b.pierce>0)b.pierce--;}}});const p=player;EnemyBulletPool.forEachActive(b=>{if(!p.alive)return;const d=Utils.dist(b.x,b.y,p.x,p.y);if(d<p.grazeRadius+b.radius&&d>p.hitboxRadius+b.radius){if(!b.grazed){b.grazed=true;p.addGraze();}}
if(d<p.hitboxRadius+b.radius){p.takeDamage();b.active=false;b.dead=true;}});for(let i=0;i<Game.enemies.length;i++){const e=Game.enemies[i];if(!e.alive)continue;if(Utils.circleHit(e.x,e.y,e.radius,p.x,p.y,p.hitboxRadius)){p.takeDamage();e.damage(99,p);}}
if(Game.boss&&Game.boss.alive&&Game.boss.state==='fight'){const boss=Game.boss;if(Utils.circleHit(boss.x,boss.y,boss.radius,p.x,p.y,p.hitboxRadius)){p.takeDamage();}}
for(let i=Game.pickups.length-1;i>=0;i--){const pk=Game.pickups[i];if(!pk.alive)continue;if(Utils.circleHit(pk.x,pk.y,pk.radius+8,p.x,p.y,p.radius)){p.pickup(pk.kind);pk.dead=true;}}},};
